def move(self, direction):
    """
    Move the player based on the specified direction and check if the game is won.
    :param direction: str, the direction of the player's movement. 
        It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

    :return: True if the game is won, False otherwise.
    """
    new_row, new_col = self.player_row, self.player_col
    if direction == 'w':
        new_row -= 1
    elif direction == 's':
        new_row += 1
    elif direction == 'a':
        new_col -= 1
    elif direction == 'd':
        new_col += 1

    if self.map[new_row][new_col] == '#':
        return False

    if (new_row, new_col) in self.boxes:
        box_new_row, box_new_col = new_row, new_col
        if direction == 'w':
            box_new_row -= 1
        elif direction == 's':
            box_new_row += 1
        elif direction == 'a':
            box_new_col -= 1
        elif direction == 'd':
            box_new_col += 1

        if self.map[box_new_row][box_new_col] == '#' or (box_new_row, box_new_col) in self.boxes:
            return False

        self.map[new_row][new_col] = ' '
        self.map[box_new_row][box_new_col] = 'X'
        self.boxes.remove((new_row, new_col))
        self.boxes.append((box_new_row, box_new_col))

    self.player_row, self.player_col = new_row, new_col
    return self.check_win()
